from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
checks=[]
def r(rel): return (ROOT/rel).read_text(encoding='utf-8')
def ck(name, ok): checks.append(ok); print(('[PASS] ' if ok else '[FAIL] ')+name)
build=r('feature/creator/build.gradle.kts'); api=r('feature/creator/src/main/java/app/voicecloud/feature/creator/data/CreatorApi.kt'); repo=r('feature/creator/src/main/java/app/voicecloud/feature/creator/data/CreatorRepository.kt'); vm=r('feature/creator/src/main/java/app/voicecloud/feature/creator/ui/CreatorViewModel.kt'); screens=r('feature/creator/src/main/java/app/voicecloud/feature/creator/ui/CreatorScreens.kt'); nav=r('app/src/main/java/app/voicecloud/android/navigation/VoiceCloudNavHost.kt'); auth_repo=r('feature/auth/src/main/java/app/voicecloud/feature/auth/data/AuthRepository.kt'); auth_vm=r('feature/auth/src/main/java/app/voicecloud/feature/auth/ui/AuthViewModel.kt')
ck('Creator module declares Compose', 'buildFeatures { compose = true }' in build)
