ck('Creator generic empty maps are explicit', 'emptyMap<Any?, Any?>()' in repo)
ck('Creator dashboard metric extraction uses firstNotNullOfOrNull safely', 'firstNotNullOfOrNull' in repo)
ck('Creator load cancellation is generation-safe', 'loadGeneration' in vm and 'generation == loadGeneration' in vm)
ck('Creator state uses StateFlow', 'StateFlow<CreatorUiState>' in vm and '.asStateFlow()' in vm)
