ck('Creator screens import rememberSaveable from saveable package', 'import androidx.compose.runtime.saveable.rememberSaveable' in screens)
ck('Creator screens import Compose Modifier', 'import androidx.compose.ui.Modifier' in screens)
ck('Creator screens use Material3 NavigationBar', 'NavigationBar {' in screens and 'NavigationBarItem(' in screens)
ck('Creator screens do not depend on experimental FlowRow', 'FlowRow' not in screens)
ck('Creator CMS uses Android Html safely', 'Html.fromHtml' in screens and 'Html.FROM_HTML_MODE_LEGACY' in screens)
ck('Creator contact fields declare email/phone keyboard types', 'KeyboardType.Email' in screens and 'KeyboardType.Phone' in screens)
ck('Creator dynamic CMS route is URI encoded and decoded', 'Uri.encode(slug.trim())' in nav and 'Uri.decode(entry.arguments?.getString("slug").orEmpty())' in nav)
ck('Creator CMS page state is cleared on route dispose', 'DisposableEffect(slug)' in nav and 'creatorViewModel.clearCmsPage()' in nav)
ck('Auth portal switching imports LastPortal', 'LastPortal.CREATOR' in auth_vm and 'LastPortal.USER' in auth_vm)
ck('cross-portal switch clears previous navigation stack', 'routeUser(user, clear = true)' in auth_vm and 'private suspend fun routeUser(user: AuthUser, clear: Boolean = false)' in auth_vm)
