ck('Auth portal switch rejects Admin and Super Admin', 'VoiceCloudRole.ADMIN, VoiceCloudRole.SUPER_ADMIN' in auth_repo[auth_repo.index('suspend fun switchPortal'):])
ck('PH10 route callbacks use method references with matching arity', all(x in nav for x in ['onSave = creatorViewModel::saveProfile','onSave = creatorViewModel::saveSettings','onSubmit = creatorViewModel::contact']))
ck('No obvious Kotlin conflict markers', not any(x in '\n'.join([api,repo,vm,screens,nav,auth_repo,auth_vm]) for x in ['<<<<<<<','>>>>>>>','=======' ]))
ck('No commented-out PH10 imports', not re.search(r'^\s*//\s*import\s+', '\n'.join([api,repo,vm,screens]), re.M))
